    if (!PairOptionalStorageRecords.insert(Record->getCanonicalDecl()).second) return true;
    for (const auto &Base : Record->bases()) {
      const auto *Child = Base.getType()->getAsCXXRecordDecl();
      if (Base.isVirtual() || !Child || !bindPairOptionalStorage(Child, Nesting + 1)) { if (Mode == UtilityTupleQueryMode::NotFnSignature || NotFnTagObservation) std::fprintf(stderr, "NOT_FN_EDGE scope=GRAPH line=7999\n"); return false; }
