      if (!Base.getTypeSourceInfo() ||
          !Context.hasSameType(Base.getTypeSourceInfo()->getType(), Base.getType()) ||
          !Source.check(Base.getTypeSourceInfo())) { if (Mode == UtilityTupleQueryMode::NotFnSignature || NotFnTagObservation) std::fprintf(stderr, "NOT_FN_EDGE scope=GRAPH line=8003\n"); return false; }
    }
    return true;
