        Pattern->isVariadic() || Pattern->hasBody() || !Pattern->getReturnType()->isVoidType() ||
        Pattern->getType()->castAs<FunctionProtoType>()->getExceptionSpecType() != EST_None ||
        Pattern->getParamDecl(0)->hasDefaultArg() ||
